/**
 * Renderers: the markdown digest (docs/reference/infinibot-knowledge.md) and
 * the compact, always-on system-prompt section for main/voice agents.
 */

import type { KnowledgeEntry, KnowledgeSnapshot } from "./types.js";

const crumb = (e: KnowledgeEntry) => e.breadcrumb.join(" › ");

export function renderDigest(snap: KnowledgeSnapshot): string {
  const L: string[] = [];
  const by = (k: KnowledgeEntry["kind"]) => snap.entries.filter((e) => e.kind === k);
  L.push(
    "# InfiniBot self-knowledge (generated)",
    "",
    "> Generated by `scripts/gen-infinibot-knowledge.ts` from the code — do not edit.",
    "> Agents query it with the `infinibot_help` tool; ids are UI target ids for navigate/highlight.",
    "",
    `Entries: ${Object.entries(snap.counts)
      .map(([k, v]) => `${k} ${v}`)
      .join(" · ")} · inputs ${snap.inputsHash}`,
    "",
    "## Sidebar",
    "",
  );
  for (const g of snap.sidebar)
    L.push(`- **${g.label}**: ${g.items.map((i) => i.label).join(", ")}`);
  L.push("", "## Plugin sidebar sections (present only while the plugin is enabled)", "");
  for (const s of snap.pluginSections)
    L.push(`- **${s.title}** (\`${s.pluginId}\`): ${s.items.map((i) => i.label).join(", ")}`);

  const table = (title: string, rows: KnowledgeEntry[]) => {
    if (!rows.length) return;
    L.push(
      "",
      `## ${title}`,
      "",
      "| Where (breadcrumb) | Route | Target id |",
      "| --- | --- | --- |",
    );
    for (const e of rows)
      L.push(`| ${crumb(e)} | ${e.route ? `\`${e.route}\`` : "—"} | \`${e.id}\` |`);
  };
  table("Pages", by("page"));
  table("Sub-tabs", by("subview"));
  table("Setup sections", by("section"));
  table("Plugins", by("plugin"));
  table("Plugin settings panels", by("plugin-settings"));
  table("Controls", by("control"));
  L.push("", "## Setup checks (sidebar glow)", "");
  for (const e of by("setup-check")) L.push(`- \`${e.id}\` — ${e.summary}`);
  L.push("", "## Plugin agent tools", "");
  for (const e of by("tool")) L.push(`- \`${e.title}\` — ${e.summary}`);
  L.push("", "## How-to flows", "");
  for (const e of by("flow").filter((f) => !f.id.startsWith("flow:learn/"))) {
    L.push(
      `### ${e.title}`,
      "",
      e.summary,
      "",
      `Where: ${crumb(e)}${e.route ? ` (\`${e.route}\`)` : ""} · id \`${e.id}\``,
      "",
    );
    for (const [i, s] of (e.steps ?? []).entries()) L.push(`${i + 1}. ${s}`);
    if (e.steps?.length) L.push("");
  }
  L.push("## Learn walkthroughs", "");
  for (const e of by("flow").filter((f) => f.id.startsWith("flow:learn/")))
    L.push(`- ${e.title} — \`${e.id}\``);
  L.push("", "## Docs ingested", "");
  for (const e of by("doc")) L.push(`- [${e.title}](../../${e.source}) — ${e.summary}`);
  L.push("");
  return L.join("\n");
}

/**
 * The always-on prompt section (main + voice orchestrator). Kept short: the
 * map is one line per sidebar group; everything else is behind infinibot_help.
 */
export function renderPromptSection(
  map: {
    sidebar: KnowledgeSnapshot["sidebar"];
    pluginSections: KnowledgeSnapshot["pluginSections"];
  },
  opts: { enabledPlugins?: string[]; plain?: boolean } = {},
): string[] {
  const enabled = opts.enabledPlugins ? new Set(opts.enabledPlugins) : null;
  const sections = map.pluginSections.filter((s) => !enabled || enabled.has(s.pluginId));
  const h = (s: string) => (opts.plain ? `[${s}]` : `## ${s}`);
  return [
    h("InfiniBot product expert"),
    "You are an expert on InfiniBot itself. The UI map (sidebar group: pages):",
    ...map.sidebar.map((g) => `- ${g.label}: ${g.items.map((i) => i.label).join(", ")}`),
    sections.length
      ? `- Plugin sections${enabled ? " (enabled)" : ""}: ${sections
          .map(
            (s) =>
              `${s.title} (${s.items
                .map((i) => i.label)
                .slice(0, 6)
                .join(", ")}${s.items.length > 6 ? ", …" : ""})`,
          )
          .join("; ")}`
      : "- Plugin sections: none enabled",
    "Plugins is its own page (Home › Plugins, /plugins); each plugin's card there has Overview, What it adds, Permissions, Settings tabs. Settings › Setup has sub-tabs Setup, Config.",
    "Rules:",
    "- NEVER invent a UI path, button or setting. For any question about where/how in InfiniBot (settings, setup, plugins, connecting accounts, why a feature or tool is unavailable) call `infinibot_help` {question} FIRST and use its breadcrumb and diagnosis verbatim.",
    "- A tool error is not a diagnosis: when a tool says something is off/unavailable, call `infinibot_help` to learn which switch it is (e.g. a plugin can be enabled while its Agent access is Off).",
    '- When the user says "navigate there", "open it", "take me there" or "show me", resolve the place from the conversation (the last breadcrumb you gave) and call `ui_control` with the `navigate` call infinibot_help returned — do not ask which screen. Then say what you opened in one sentence.',
    "- ui_control find_text / scroll_by / click_text cannot see inside plugin and settings panels. Never use them to look for a setting — one navigate call, then describe the spot in words.",
    "- After navigating, stop: do not scroll, find_text or click around to hunt for a control. Tell the user where it is on the page (infinibot_help `navigate.thenLookFor`) and let them change owner settings (agent access, permissions, API keys) themselves.",
    "- Owner-only settings (plugin agent access, permissions, API keys, enabling plugins) can't be changed by agents: offer to OPEN the page, never offer to change them yourself.",
    "- Describe controls exactly as infinibot_help does (option cards vs dropdown, applies immediately vs Save). Never add gear icons, menus or Save buttons it doesn't mention.",
    "- The navigate call infinibot_help returns is for YOU to execute with ui_control. Never paste JSON, tool names (ui_control, switch_tab) or tab ids into a reply — the user only ever sees breadcrumbs like Solatrix › Settings.",
    "- Never tell the user to run raw JSON, RPC calls or config edits when a UI control exists; give the breadcrumb and offer to open it.",
  ];
}
